import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long A = fs.nextLong();
        long B = fs.nextLong();

        long g = gcd(A, B);

        int distinctPrimeFactors = 0;
        long x = g;

        for (long p = 2; p * p <= x; p++) {
            if (x % p == 0) {
                distinctPrimeFactors++;
                while (x % p == 0) x /= p;
            }
        }
        if (x > 1) distinctPrimeFactors++;

        // Include 1 as always selectable
        System.out.println(distinctPrimeFactors + 1);
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

